import React, { useState, useEffect } from 'react';
import { ArrowUp, Mail, Shield, Smartphone, Server, Eye, Lock, Globe } from 'lucide-react';
import Section from './Section';

interface SectionProps {
  id: string;
  title: string;
  children: React.ReactNode;
  icon?: React.ReactNode;
}

const ScrollToTopButton: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const toggleVisibility = () => {
      if (window.pageYOffset > 300) {
        setIsVisible(true);
      } else {
        setIsVisible(false);
      }
    };

    window.addEventListener('scroll', toggleVisibility);
    return () => window.removeEventListener('scroll', toggleVisibility);
  }, []);

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth',
    });
  };

  return (
    <button
      onClick={scrollToTop}
      className={`fixed bottom-8 right-8 z-50 p-2 rounded-full bg-blue-500 text-white transition-all duration-300 ${isVisible ? 'opacity-100' : 'opacity-0 pointer-events-none'
        } focus:outline-none focus:ring-2 focus:ring-blue-400 focus:ring-offset-2`}
      aria-label="Voltar ao topo"
    >
      <ArrowUp size={24} />
    </button>
  );
};

const Section: React.FC<SectionProps> = ({ id, title, children, icon }) => (
  <section id={id} className="mb-12 scroll-mt-24 bg-white p-6 md:p-8 rounded-2xl shadow-sm border border-slate-100">
    <div className="flex items-center gap-3 mb-4">
      {icon && <div className="text-blue-600">{icon}</div>}
      <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
    </div>
    <div className="prose prose-slate max-w-none text-slate-600 leading-relaxed space-y-4">
      {children}
    </div>
  </section>
);

const App: React.FC = () => {
  const [data, setData] = useState<any>({});
  const [isLoading, setIsLoading] = useState(true);

